import{_ as i,C as a,o as r,c as s,j as t,a as n,E as l,a2 as u}from"./chunks/framework.BxGh02fV.js";const q=JSON.parse('{"title":"Git","description":"","frontmatter":{"title":"Git"},"headers":[],"relativePath":"guide/git.md","filePath":"guide/git.md"}'),c={name:"guide/git.md"};function d(m,e,p,h,g,f){const o=a("Capture");return r(),s("div",null,[e[0]||(e[0]=t("h1",{id:"git",tabindex:"-1"},[n("Git "),t("a",{class:"header-anchor",href:"#git","aria-label":'Permalink to "Git"'},"​")],-1)),e[1]||(e[1]=t("p",null,"Cet écran montre l'état git local du workspace et permet de committer les métadonnées d'Effortless sans quitter l'application. Vous y venez pour voir ce qui a changé, ou pour enregistrer l'état du suivi dans l'historique.",-1)),l(o,{name:"git",alt:"L'écran Git : branche, fichiers modifiés et identité git de chaque dépôt"}),e[2]||(e[2]=u('<h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><p>Sous le titre <strong>Git (local)</strong>, quatre cartes se suivent de haut en bas. La capture n&#39;en montre que le début ; faites défiler l&#39;écran pour voir la suite.</p><ol><li><strong>Branche</strong> et <strong>Fichiers modifiés</strong> : la branche courante, puis la liste des fichiers modifiés. Si l&#39;arbre est propre, l&#39;écran affiche « Répertoire de travail propre. » Si le dossier n&#39;est pas un dépôt, il affiche « Ce répertoire n&#39;est pas un dépôt git. »</li><li><strong>Identité git</strong> : le nom et l&#39;e-mail de votre profil, puis chaque dépôt (le projet, et chaque module qui a son propre dépôt) avec l&#39;identité qui y signe les commits et sa portée (<code>local</code> ou <code>global</code>). Une coche verte : le dépôt signe avec votre profil ; une croix rouge : il s&#39;en écarte.</li><li><strong>Auto-commit des métadonnées</strong>, <strong>Message de commit</strong> et le bouton <strong>Committer les métadonnées</strong>.</li><li><strong>Derniers commits</strong> : un tableau (<strong>Hash</strong>, <strong>Sujet</strong>, <strong>Date</strong>) des dix derniers commits, et un bouton <strong>Rafraîchir</strong>.</li></ol><h2 id="ce-que-vous-pouvez-faire" tabindex="-1">Ce que vous pouvez faire <a class="header-anchor" href="#ce-que-vous-pouvez-faire" aria-label="Permalink to &quot;Ce que vous pouvez faire&quot;">​</a></h2><h3 id="signer-avec-l-identite-du-profil" tabindex="-1">Signer avec l&#39;identité du profil <a class="header-anchor" href="#signer-avec-l-identite-du-profil" aria-label="Permalink to &quot;Signer avec l&#39;identité du profil&quot;">​</a></h3><p>Les commits qu&#39;Effortless lance portent déjà votre nom et votre e-mail. Ceux que vous faites à la main suivent la config git du dépôt : si elle porte une autre identité, vos commits ne vous sont pas attribués. Un tel dépôt apparaît aussi dans <strong>Ce qui t&#39;attend</strong> du tableau de bord.</p><ol><li>Cliquez sur <strong>Poser l&#39;identité du profil…</strong>. Le bouton n&#39;apparaît que si un dépôt s&#39;écarte.</li><li>Relisez ce qui sera écrit, puis cliquez sur <strong>Poser</strong>. Votre nom et votre e-mail vont dans la config git <strong>locale</strong> de chaque dépôt qui s&#39;écarte ; votre config globale n&#39;est jamais touchée. <strong>Annuler</strong> ne change rien.</li></ol><p>La carte dit aussi si l&#39;e-mail du profil est rattaché à votre compte GitHub : « Courriel rattaché au compte GitHub … », « Courriel absent du compte GitHub … » (vos commits ne vous seront pas attribués), ou « Courriel non vérifié auprès de GitHub » avec son motif. Pour que la vérification se fasse, <code>gh</code> doit être installé et connecté avec la portée <code>user</code> : <code>gh auth refresh -h github.com -s user</code>.</p><h3 id="activer-l-auto-commit" tabindex="-1">Activer l&#39;auto-commit <a class="header-anchor" href="#activer-l-auto-commit" aria-label="Permalink to &quot;Activer l&#39;auto-commit&quot;">​</a></h3><p>Cochez <strong>Auto-commit des métadonnées</strong>. Effortless committe alors automatiquement <code>.effortless</code> et <code>blueprints</code> après chaque action faite dans l&#39;application (ADR, BQO, tâche, phase). Il ne committe jamais de code. Chaque auto-commit s&#39;annonce par une notification (« Auto-commit … » suivi du hash), ou dit pourquoi il a été ignoré.</p><p>La case n&#39;est pas mémorisée : elle repart décochée quand vous revenez au sélecteur ou aux préférences, et à chaque lancement.</p><h3 id="committer-les-metadonnees-a-la-main" tabindex="-1">Committer les métadonnées à la main <a class="header-anchor" href="#committer-les-metadonnees-a-la-main" aria-label="Permalink to &quot;Committer les métadonnées à la main&quot;">​</a></h3><ol><li>Saisissez un <strong>Message de commit</strong>. S&#39;il reste vide, Effortless utilise <code>chore(effortless): mise à jour des métadonnées</code>.</li><li>Cliquez sur <strong>Committer les métadonnées</strong>.</li></ol><p>L&#39;écran affiche « Commit créé : » suivi du hash. Le bouton est désactivé si le dossier n&#39;est pas un dépôt git.</p><h3 id="relire-l-historique" tabindex="-1">Relire l&#39;historique <a class="header-anchor" href="#relire-l-historique" aria-label="Permalink to &quot;Relire l&#39;historique&quot;">​</a></h3><p>Cliquez sur <strong>Rafraîchir</strong> pour relire l&#39;état et la liste des commits.</p><h2 id="conseils" tabindex="-1">Conseils <a class="header-anchor" href="#conseils" aria-label="Permalink to &quot;Conseils&quot;">​</a></h2><ul><li>Ce bouton ne committe que les métadonnées. Vos fichiers de code restent à committer vous-même ; le hook de l&#39;écran <a href="/Effortless/guide/drift.html">Dérive</a> vérifiera alors qu&#39;une tâche est en cours.</li><li>Une branche affichée « (aucune) » signifie que le dépôt n&#39;a pas encore de commit ou n&#39;est pas rattaché à une branche. Sans aucun commit, le tableau affiche « Aucun commit dans l&#39;historique. »</li></ul>',18))])}const b=i(c,[["render",d]]);export{q as __pageData,b as default};
